// Sauvegarde chaque fichier image reçu sur le disque local
// et retourne la liste des chemins
const fs = require('fs');
const path = require('path');

const UPLOAD_DIR = 'C:\Users\HP\Downloads\prjt_fixed2\data\uploads';
if (!fs.existsSync(UPLOAD_DIR)) fs.mkdirSync(UPLOAD_DIR, { recursive: true });

const fichiersSauvegardes = [];
const items = $input.all();

for (const item of items) {
  const body = item.json.body || {};
  const files = item.binary || {};

  // Traiter chaque fichier binaire uploadé
  for (const [key, file] of Object.entries(files)) {
    const nomFichier = file.fileName || `scan_${Date.now()}.jpg`;
    const cheminSortie = path.join(UPLOAD_DIR, nomFichier);

    // Décoder base64 et sauvegarder
    const buffer = Buffer.from(file.data, 'base64');
    fs.writeFileSync(cheminSortie, buffer);

    fichiersSauvegardes.push({
      nom: nomFichier,
      chemin: cheminSortie,
      taille: buffer.length
    });
  }
}

return [{ json: { fichiers: fichiersSauvegardes, nb_fichiers: fichiersSauvegardes.length } }];

// Vérifier que l'OCR a réussi
const stdout = $input.first().json.stdout || '';
const stderr = $input.first().json.stderr || '';
const exitCode = $input.first().json.exitCode;

if (exitCode !== 0) {
  return [{ json: { statut: 'erreur_ocr', message: stderr.substring(0, 500) } }];
}

return [{ json: { statut: 'ocr_ok', log: stdout.substring(0, 200) } }];

// Parser le JSON retourné par CrewAI (stdout seulement)
const stdout = $input.first().json.stdout || '{}';
const exitCode = $input.first().json.exitCode;

// Extraire la dernière ligne JSON valide du stdout
const lignes = stdout.trim().split('\n');
let resultat = null;

for (let i = lignes.length - 1; i >= 0; i--) {
  try {
    const parsed = JSON.parse(lignes[i].trim());
    if (parsed.statut || parsed.nb_suspects !== undefined || parsed.copies_suspectes) {
      resultat = parsed;
      break;
    }
  } catch(e) {}
}

if (!resultat) {
  resultat = { statut: 'erreur_parsing', raw: stdout.substring(0, 300) };
}

return [{ json: resultat }];
